      "id": "arxiv:2608.25457v2",
      "title": "MACGen: Toward Functionally Correct and Secure Code Generation via Multi-Agent Collaboration",
      "url": "https://arxiv.org/abs/2608.25457v2",
      "pdfUrl": "https://arxiv.org/pdf/2608.25457v2",
      "source": "arXiv",
